//! Ported from `tests/Sobreiro.Tests/AlertPolicyTests.cs`.
use chrono::{DateTime, TimeDelta, Utc};
use sobreiro_core::alerts::alert_policy::{self, Alert, THRESHOLDS};
use sobreiro_core::alerts::alert_state::{AlertMark, AlertState};
use sobreiro_core::display::{PaceDays, Zone};
use sobreiro_core::limits::{Limit, LimitKind};

use crate::{NONE, at_ticks, en_us, maybe_at, oracle_clock, oracle_zone, span, time};

fn now() -> DateTime<Utc> {
    time("2026-11-09T10:00:00Z")
}

fn make(kind: LimitKind, percent: f64, resets: Option<DateTime<Utc>>, is_reset: bool) -> Limit {
    let label = match kind {
        LimitKind::Session => "Session",
        LimitKind::Weekly => "Weekly",
        LimitKind::Spend => "Spend",
        LimitKind::Credits => "Credits",
    };
    Limit::new("Claude Code", kind, label, percent, resets, now(), is_reset)
}

fn session(
    percent: f64,
    resets_in: Option<TimeDelta>,
    is_reset: bool,
    window: Option<TimeDelta>,
) -> Limit {
    let resets_in = resets_in.unwrap_or(TimeDelta::hours(3));
    Limit {
        window,
        ..make(
            LimitKind::Session,
            percent,
            Some(now() + resets_in),
            is_reset,
        )
    }
}

/// A session limit that resets in three hours and has no window.
fn session_at(percent: f64) -> Limit {
    session(percent, None, false, None)
}

fn check(state: &AlertState, limits: &[Limit]) -> (Vec<Alert>, Option<AlertState>) {
    alert_policy::check(
        limits,
        state,
        now(),
        &Zone::utc(),
        &en_us(),
        PaceDays::EveryDay,
    )
}

fn single(alerts: Vec<Alert>) -> Alert {
    assert_eq!(alerts.len(), 1, "{alerts:?}");
    alerts.into_iter().next().unwrap()
}

#[test]
fn thresholds_are_80_and_95() {
    assert_eq!(THRESHOLDS, [80, 95]);
}

#[test]
fn below_80_gives_no_alert() {
    let (alerts, next) = check(&AlertState::empty(), &[session_at(79.0)]);
    assert!(alerts.is_empty());
    assert!(next.is_none());
}

#[test]
fn reaching_80_alerts_once_with_title_and_body_and_marks_the_period() {
    let (alerts, next) = check(
        &AlertState::empty(),
        &[session(80.0, None, false, Some(TimeDelta::hours(24)))],
    );
    let alert = single(alerts);
    assert_eq!(alert.kind, LimitKind::Session);
    assert_eq!(alert.threshold, 80);
    assert_eq!(alert.title, "Session 80% used");
    assert_eq!(alert.body, "On track \u{b7} resets in 3h");
    assert_eq!(
        next.unwrap().marks[&LimitKind::Session],
        AlertMark {
            resets_at: Some(now() + TimeDelta::hours(3)),
            threshold: 80
        }
    );
}

#[test]
fn body_without_a_status_is_just_the_resets_in_text() {
    let (alerts, _) = check(&AlertState::empty(), &[session_at(80.0)]);
    assert_eq!(single(alerts).body, "resets in 3h");
}

#[test]
fn body_with_a_run_out_time() {
    let (alerts, _) = check(
        &AlertState::empty(),
        &[session(90.0, None, false, Some(TimeDelta::hours(5)))],
    );
    assert_eq!(single(alerts).body, "Ends 10:13 AM \u{b7} resets in 3h");
}

#[test]
fn title_uses_the_floored_percent() {
    let (alerts, _) = check(&AlertState::empty(), &[session_at(83.9)]);
    assert_eq!(single(alerts).title, "Session 83% used");
}

#[test]
fn same_period_at_85_does_not_alert_again_and_state_is_unchanged() {
    let (_, marked) = check(&AlertState::empty(), &[session_at(80.0)]);
    let marked = marked.unwrap();
    let (alerts, next) = check(&marked, &[session_at(85.0)]);
    assert!(alerts.is_empty());
    assert!(next.is_none());
}

#[test]
fn reaching_95_alerts_after_80() {
    let (_, marked) = check(&AlertState::empty(), &[session_at(80.0)]);
    let marked = marked.unwrap();
    let (alerts, next) = check(&marked, &[session_at(96.0)]);
    assert_eq!(single(alerts).threshold, 95);
    assert_eq!(next.unwrap().marks[&LimitKind::Session].threshold, 95);
}

#[test]
fn jumping_from_50_to_97_gives_a_single_95_alert() {
    // 50% is under 80, so nothing changes and the state stays what it was.
    let (_, low) = check(&AlertState::empty(), &[session_at(50.0)]);
    assert!(low.is_none());
    let (alerts, _) = check(&AlertState::empty(), &[session_at(97.0)]);
    assert_eq!(single(alerts).threshold, 95);
}

#[test]
fn a_new_period_alerts_again() {
    let (_, marked) = check(&AlertState::empty(), &[session_at(90.0)]);
    let marked = marked.unwrap();
    let (alerts, next) = check(
        &marked,
        &[session(82.0, Some(TimeDelta::hours(9)), false, None)],
    );
    assert_eq!(single(alerts).threshold, 80);
    assert_eq!(
        next.unwrap().marks[&LimitKind::Session].resets_at,
        Some(now() + TimeDelta::hours(9))
    );
}

#[test]
fn a_reset_limit_gives_no_alert() {
    let (alerts, _) = check(&AlertState::empty(), &[session(90.0, None, true, None)]);
    assert!(alerts.is_empty());
}

#[test]
fn a_limit_with_neither_status_nor_resets_in_has_an_empty_body() {
    let (alerts, _) = check(
        &AlertState::empty(),
        &[make(LimitKind::Session, 90.0, None, false)],
    );
    assert_eq!(single(alerts).body, "");
}

#[test]
fn a_limit_without_a_reset_time_alerts_with_an_empty_body() {
    let (alerts, _) = check(
        &AlertState::empty(),
        &[make(LimitKind::Spend, 85.0, None, false)],
    );
    assert_eq!(single(alerts).body, "");
}

#[test]
fn several_alerts_come_highest_threshold_first_then_by_kind() {
    let weekly = make(
        LimitKind::Weekly,
        97.0,
        Some(now() + TimeDelta::days(3)),
        false,
    );
    let spend = make(
        LimitKind::Spend,
        85.0,
        Some(now() + TimeDelta::days(10)),
        false,
    );
    let (alerts, _) = check(&AlertState::empty(), &[spend, session_at(85.0), weekly]);
    let kinds: Vec<LimitKind> = alerts.iter().map(|alert| alert.kind).collect();
    assert_eq!(
        kinds,
        [LimitKind::Weekly, LimitKind::Session, LimitKind::Spend]
    );
}

#[test]
fn weekly_and_session_both_over_80_give_session_first() {
    let weekly = make(
        LimitKind::Weekly,
        85.0,
        Some(now() + TimeDelta::days(3)),
        false,
    );
    let (alerts, _) = check(&AlertState::empty(), &[weekly, session_at(85.0)]);
    let kinds: Vec<LimitKind> = alerts.iter().map(|alert| alert.kind).collect();
    assert_eq!(kinds, [LimitKind::Session, LimitKind::Weekly]);
}

fn credits(percent: f64, is_reset: bool) -> Limit {
    Limit::new(
        "GitHub Copilot",
        LimitKind::Credits,
        "AI credits",
        percent,
        Some(now() + TimeDelta::days(20)),
        now(),
        is_reset,
    )
}

#[test]
fn credits_at_80_toasts_with_copilot_title() {
    let (alerts, next) = check(&AlertState::empty(), &[credits(80.0, false)]);
    let alert = single(alerts);
    assert_eq!(alert.kind, LimitKind::Credits);
    assert_eq!(alert.title, "Copilot AI credits 80% used");
    assert!(next.unwrap().marks.contains_key(&LimitKind::Credits));
}

#[test]
fn reset_credits_never_toast() {
    let (alerts, _) = check(&AlertState::empty(), &[credits(90.0, true)]);
    assert!(alerts.is_empty());
}

#[test]
fn a_percent_that_is_not_a_number_gives_no_alert() {
    // NaN is shown as 0%, in 1.x as here, so it crosses no threshold.
    let (alerts, next) = check(&AlertState::empty(), &[session_at(f64::NAN)]);
    assert!(alerts.is_empty());
    assert!(next.is_none());
}

#[test]
fn claude_titles_unchanged() {
    let (alerts, _) = check(&AlertState::empty(), &[session_at(80.0)]);
    assert_eq!(single(alerts).title, "Session 80% used");
}

#[test]
fn the_alert_body_follows_the_pace_setting() {
    // A Saturday.
    let at = time("2026-11-14T10:00:00Z");
    let weekly = Limit {
        window: Some(TimeDelta::days(7)),
        ..Limit::new(
            "Claude Code",
            LimitKind::Weekly,
            "Weekly",
            80.0,
            Some(time("2026-11-16T00:00:00Z")),
            at,
            false,
        )
    };
    let run = |days| {
        alert_policy::check(
            std::slice::from_ref(&weekly),
            &AlertState::empty(),
            at,
            &Zone::utc(),
            &en_us(),
            days,
        )
        .0
    };
    assert!(single(run(PaceDays::EveryDay)).body.starts_with("Ends "));
    assert!(
        single(run(PaceDays::Weekdays))
            .body
            .starts_with("On track \u{b7} ")
    );
}

// ---- oracle ----
/// A limit as a row of the oracle holds it: the kind, the provider, the label, the percent, when
/// it resets, its window, when it was read and whether it is reset.
type OracleLimit = (
    &'static str,
    &'static str,
    &'static str,
    f64,
    i64,
    i64,
    i64,
    bool,
);

/// A mark of the state: the kind, when its period resets and the threshold.
type OracleMark = (&'static str, i64, i32);

/// An alert: the kind, the threshold, the title and the body.
type OracleAlert = (&'static str, i32, &'static str, &'static str);

/// The zone, the clock, the day choice, now, the limits, the state before, the alerts and the
/// state after (none when the C# gave back the state it was given).
type OracleRow = (
    &'static str,
    &'static str,
    &'static str,
    i64,
    &'static [OracleLimit],
    &'static [OracleMark],
    &'static [OracleAlert],
    Option<&'static [OracleMark]>,
);

fn kind_named(name: &str) -> LimitKind {
    match name {
        "Session" => LimitKind::Session,
        "Weekly" => LimitKind::Weekly,
        "Spend" => LimitKind::Spend,
        "Credits" => LimitKind::Credits,
        _ => panic!("no kind named {name}"),
    }
}

fn ticks_of(moment: Option<DateTime<Utc>>) -> i64 {
    moment.map_or(NONE, |at| {
        (at - at_ticks(0)).num_nanoseconds().unwrap() / 100
    })
}

fn state_of_rows(rows: &[OracleMark]) -> AlertState {
    AlertState {
        marks: rows
            .iter()
            .map(|&(kind, resets, threshold)| {
                (
                    kind_named(kind),
                    AlertMark {
                        resets_at: maybe_at(resets),
                        threshold,
                    },
                )
            })
            .collect(),
    }
}

fn rows_of_state(state: &AlertState) -> Vec<(String, i64, i32)> {
    state
        .marks
        .iter()
        .map(|(kind, mark)| {
            (
                format!("{kind:?}"),
                ticks_of(mark.resets_at),
                mark.threshold,
            )
        })
        .collect()
}

fn rows_of_marks(rows: &[OracleMark]) -> Vec<(String, i64, i32)> {
    rows.iter()
        .map(|&(kind, resets, threshold)| (kind.to_string(), resets, threshold))
        .collect()
}

#[test]
fn check_answers_as_the_csharp_did() {
    for (zone, culture, days, now, limits, state, alerts, next) in ROWS {
        let limits: Vec<Limit> = limits
            .iter()
            .map(
                |&(kind, provider, label, percent, resets, window, observed, is_reset)| {
                    let mut limit = Limit::new(
                        provider,
                        kind_named(kind),
                        label,
                        percent,
                        maybe_at(resets),
                        at_ticks(observed),
                        is_reset,
                    );
                    limit.window = (window != NONE).then(|| span(window));
                    limit
                },
            )
            .collect();
        let days = match *days {
            "every" => PaceDays::EveryDay,
            _ => PaceDays::Weekdays,
        };
        let before = state_of_rows(state);
        let (got, got_next) = alert_policy::check(
            &limits,
            &before,
            at_ticks(*now),
            &oracle_zone(zone),
            &oracle_clock(culture),
            days,
        );
        let got: Vec<(String, i32, String, String)> = got
            .into_iter()
            .map(|alert| {
                (
                    format!("{:?}", alert.kind),
                    alert.threshold,
                    alert.title,
                    alert.body,
                )
            })
            .collect();
        let expected: Vec<(String, i32, String, String)> = alerts
            .iter()
            .map(|&(kind, threshold, title, body)| {
                (
                    kind.to_string(),
                    threshold,
                    title.to_string(),
                    body.to_string(),
                )
            })
            .collect();
        let at = format!("{zone} {culture} {days:?} at {now}: {limits:?} after {state:?}");
        assert_eq!(got, expected, "{at}");
        assert_eq!(
            got_next.as_ref().map(rows_of_state),
            next.map(rows_of_marks),
            "{at}"
        );
    }
}

#[test]
fn the_rows_hold_alerts_and_unchanged_states() {
    let with_alerts = ROWS.iter().filter(|row| !row.6.is_empty()).count();
    let unchanged = ROWS.iter().filter(|row| row.7.is_none()).count();
    assert!(with_alerts > 200, "{with_alerts}");
    assert!(unchanged > 100, "{unchanged}");
    for kind in ["Session", "Weekly", "Spend", "Credits"] {
        assert!(ROWS.iter().any(|row| row.6.iter().any(|a| a.0 == kind)));
    }
    for threshold in [80, 95] {
        assert!(
            ROWS.iter()
                .any(|row| row.6.iter().any(|a| a.1 == threshold))
        );
    }
}

